/**
 * App logo mark.
 *
 * v3.2: Mr. Magic's own emerald-and-gold artwork (crescent, mosque dome,
 * 21 calendar) is now the brand — the same image as the installed app
 * icon. The source lives in brand-source/ and the served files are
 * generated by scripts/generate-brand.py.
 *
 * v3.1 history: the mark was an original SVG (sunrise over a leaf whose
 * vein is a check mark). It still lives in the DaySummaryCard PNG export
 * as the corner motif, and in git history / the v3.1 stage zips.
 *
 * Decorative wherever the app name already appears as text (aria-hidden).
 */
export function LogoMark({ size = 46 }: { size?: number }) {
  return (
    <img
      src="/icons/icon-512.png"
      alt=""
      aria-hidden="true"
      width={size}
      height={size}
      style={{
        display: 'block',
        flexShrink: 0,
        borderRadius: Math.round(size * 0.24),
        boxShadow: '0 2px 10px rgba(6, 40, 24, 0.35)',
      }}
    />
  );
}
